def valid(directory):
    try:
        for name,expected in FILES.items():
            path=directory/name
            if path.is_symlink() or hashlib.sha256(path.read_bytes()).hexdigest()!=expected:return False
        return True
    except OSError:return False

def install(base):
    base.mkdir(parents=True,exist_ok=True)
    destination=base/PAYLOAD_SHA256[:24]
    with (base/'.install.lock').open('a') as handle:
        fcntl.flock(handle,fcntl.LOCK_EX)
        if valid(destination):return destination
        data=base64.b85decode(PAYLOAD)
        if hashlib.sha256(data).hexdigest()!=PAYLOAD_SHA256:raise ValueError('Embedded payload checksum differs')
        stage=pathlib.Path(tempfile.mkdtemp(prefix='.install-',dir=base))
        try:
            with tarfile.open(fileobj=io.BytesIO(data),mode='r:gz') as archive:
                members=archive.getmembers()
                if {m.name for m in members}!=set(FILES):raise ValueError('Payload file list differs')
                for member in members:
                    if not member.isfile() or member.name not in FILES or '..' in pathlib.PurePosixPath(member.name).parts:
                        raise ValueError('Unexpected installation member')
                    content=archive.extractfile(member).read()
                    if hashlib.sha256(content).hexdigest()!=FILES[member.name]:raise ValueError('Module checksum differs')
                    target=stage/member.name;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(content)
            if destination.exists():
                os.rename(destination,base/(destination.name+'.previous-'+str(time.time_ns())))
            os.rename(stage,destination)
            return destination
        finally:
            if stage.exists():shutil.rmtree(stage)

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--round',type=int,choices=(1,5,6),required=True,dest='round_number')
    parser.add_argument('--root',default='/public/home/zhuziyuan/projects/paper3')
    parser.add_argument('--install-base',default=str(pathlib.Path.home()/'paper3-parallel-migrations'))
    parser.add_argument('--old-job')
    parser.add_argument('--credentials')
    parser.add_argument('--direct-package')
    parser.add_argument('--payload-manifest')
    parser.add_argument('--scientific-package')
    parser.add_argument('--execute',action='store_true')
    parser.add_argument('--install-only',action='store_true')
    args=parser.parse_args()
    package=install(pathlib.Path(args.install_base).expanduser())
    print(json.dumps({'status':'PARALLEL_PACKAGE_VERIFIED','package':str(package),'round':args.round_number,
          'payload_sha256':PAYLOAD_SHA256,'school_jobs_submitted_by_installer':False}),flush=True)
    if args.install_only:return 0
    folder=package/('round1' if args.round_number==1 else 'round56')
    command=[sys.executable,'-I','-S','-B','-u',str(folder/'START.py'),'--root',args.root,'--python',sys.executable]
    if args.round_number!=1:command+=['--round',str(args.round_number)]
    if args.old_job:command+=['--old-job',args.old_job]
    if args.credentials:command+=['--credentials',args.credentials]
    for name in ('direct_package','payload_manifest','scientific_package'):
        value=getattr(args,name)
        if value:
            if (args.round_number==1)==(name=='scientific_package'):parser.error('Package option does not apply to this round')
            command+=['--'+name.replace('_','-'),value]
    if args.execute:command+=['--execute']
    return subprocess.run(command).returncode

if __name__=='__main__':raise SystemExit(main())
